{"skill": "async (b) => {
  const tiles = [];
  for (let x = 7; x <= 9; x++) for (let y = 3; y <= 5; y++) tiles.push([x, y]);
  for (const [x, y] of tiles) {
    await b.workTile(x, y, 0, 'ControllerX');
    await b.workTile(x, y, 2, 'ControllerA');
    await b.workTile(x, y, 1, 'ControllerX');
  }
  return true;
}", "check": "async (b) => {
  const obs = await b.observe();
  const items = await b.items();
  const seeds = items.find(i => i.name && i.name.toLowerCase().includes('parsnip'));
  const used = seeds ? (6 - seeds.stack) : 6;
  const ok = used >= 6;
  return {ok, detail: 'parsnip seeds used: ' + used + '; obs snippet: ' + obs.slice(0, 200)};
}"}
